    const roi =
      developmentInitialCost > 0
        ? ((totalCumulativeReduction / developmentInitialCost) * 100)
        : 0;
  
    const finalBreakEvenYear = breakEvenYear === -1 ? simulationYears + 1 : breakEvenYear;
  
