/* AIVIC_FUNCTION_BUNDLE_START owner=calculateInvestmentDecision exports=calculateInvestmentDecision */
const __aivicBundle_18_calculateInvestmentDecision = (() => {
  function calculateInvestmentDecision(input: {
    salesforceLicenseCostPerYear: number;
    developmentInitialCost: number;
    maintenanceCostPerYear: number;
    roiThreshold: number;
    analysisYears: number;
  }): {
    isApproved: boolean;
    roi: number;
    roiThreshold: number;
    rejectionReason?: string;
    salesforceCumulativeCost: number;
    developmentCumulativeCost: number;
    annualSavings: number;
    decisionStatus: string;
    recordId: string;
    timestamp: string;
  } {
    const {
      salesforceLicenseCostPerYear,
      developmentInitialCost,
      maintenanceCostPerYear,
      roiThreshold,
      analysisYears,
    } = input;
  
    const salesforceCumulativeCost = salesforceLicenseCostPerYear * analysisYears;
    const developmentCumulativeCost =
      developmentInitialCost + maintenanceCostPerYear * analysisYears;
  
    const netSavings = salesforceCumulativeCost - developmentCumulativeCost;
    const roi = netSavings / developmentInitialCost;
  
    const annualSavings = netSavings / analysisYears;
  
    const isApproved = roi >= roiThreshold;
    const decisionStatus = isApproved ? "APPROVED" : "REJECTED";
  
    let rejectionReason: string | undefined;
    if (!isApproved) {
      rejectionReason = `ROI が閾値未満です。現在のROI: ${roi.toFixed(4)}, 必要な閾値: ${roiThreshold}`;
    }
  
    const recordId = `REC-${randomUUID()}`;
    const timestamp = new Date().toISOString();
  
    return {
      isApproved,
      roi,
      roiThreshold,
      rejectionReason,
      salesforceCumulativeCost,
      developmentCumulativeCost,
      annualSavings,
      decisionStatus,
      recordId,
      timestamp,
    };
  }
  return { calculateInvestmentDecision };
})();
export const calculateInvestmentDecision = __aivicBundle_18_calculateInvestmentDecision.calculateInvestmentDecision;
