/* AIVIC_FUNCTION_BUNDLE_START owner=calculateLicenseCostComparison exports=calculateLicenseCostComparison */
const __aivicBundle_20_calculateLicenseCostComparison = (() => {
  function calculateLicenseCostComparison(input: {
    roi_threshold_percent: number;
    current_salesforce_annual_license_cost: number;
    system_initial_construction_cost: number;
    system_annual_maintenance_cost: number;
    target_reduction_percent?: number;
    approver_user_id: string;
    approval_timestamp_iso: string;
  }): {
    approval_status: string;
    is_approved: boolean;
    roi_percent: number;
    actual_reduction_percent: number;
    three_year_cumulative_cost_salesforce: number;
    three_year_cumulative_cost_system: number;
    annual_cost_reduction: number;
    approver_user_id: string;
    approval_datetime: string;
  } {
    const {
      roi_threshold_percent,
      current_salesforce_annual_license_cost,
      system_initial_construction_cost,
      system_annual_maintenance_cost,
      approver_user_id,
      approval_timestamp_iso,
    } = input;
  
    // Calculate 3-year cumulative costs
    const three_year_cumulative_cost_salesforce =
      current_salesforce_annual_license_cost * 3;
    const three_year_cumulative_cost_system =
      system_initial_construction_cost + system_annual_maintenance_cost * 3;
  
    // Calculate 3-year cost reduction
    const three_year_cost_reduction =
      three_year_cumulative_cost_salesforce - three_year_cumulative_cost_system;
  
    // Calculate ROI percentage
    const roi_percent =
      (three_year_cost_reduction / system_initial_construction_cost) * 100;
  
    // Calculate actual reduction percentage
    const actual_reduction_percent =
      (three_year_cost_reduction / three_year_cumulative_cost_salesforce) * 100;
  
    // Calculate annual cost reduction
    const annual_cost_reduction = three_year_cost_reduction / 3;
  
    // Determine approval status based on ROI threshold
    const is_approved = roi_percent >= roi_threshold_percent;
    const approval_status = is_approved ? 'approved' : 'rejected';
  
    return {
      approval_status,
      is_approved,
      roi_percent,
      actual_reduction_percent,
      three_year_cumulative_cost_salesforce,
      three_year_cumulative_cost_system,
      annual_cost_reduction,
      approver_user_id,
      approval_datetime: approval_timestamp_iso,
    };
  }
  return { calculateLicenseCostComparison };
})();
