/* AIVIC_FUNCTION_BUNDLE_START owner=evaluateTrainingCompletionReadiness exports=evaluateTrainingCompletionReadiness */
const __aivicBundle_23_evaluateTrainingCompletionReadiness = (() => {
  function evaluateTrainingCompletionReadiness(input: {
    trainingCompletionRate?: number;
    manualComprehensionScore?: number;
    systemOperationProficiencyScore?: number;
    deploymentPhase?: string;
  }): {
    status: string;
    isReadyForCutover: boolean;
    readinessScore: number;
    missingIndicators: string[];
    evaluationTimestamp: string;
  } {
    const MINIMUM_THRESHOLD = 0.85;
  
    // Validate trainingCompletionRate
    if (
      input.trainingCompletionRate === undefined ||
      input.trainingCompletionRate === null
    ) {
      throw new Error("研修実施率が指定されていません");
    }
    if (
      input.trainingCompletionRate < 0 ||
      input.trainingCompletionRate > 1
    ) {
      throw new Error("研修実施率は0から1の範囲で指定してください");
    }
  
    // Validate manualComprehensionScore
    if (
      input.manualComprehensionScore === undefined ||
      input.manualComprehensionScore === null
    ) {
      throw new Error("マニュアル理解度が指定されていません");
    }
    if (
      input.manualComprehensionScore < 0 ||
      input.manualComprehensionScore > 1
    ) {
      throw new Error("マニュアル理解度は0から1の範囲で指定してください");
    }
  
    // Validate systemOperationProficiencyScore
    if (
      input.systemOperationProficiencyScore === undefined ||
      input.systemOperationProficiencyScore === null
    ) {
      throw new Error("操作習熟度が指定されていません");
    }
    if (
      input.systemOperationProficiencyScore < 0 ||
      input.systemOperationProficiencyScore > 1
    ) {
      throw new Error("操作習熟度は0から1の範囲で指定してください");
    }
  
    // Calculate readiness score as average of three indicators
    const readinessScore =
      (input.trainingCompletionRate +
        input.manualComprehensionScore +
        input.systemOperationProficiencyScore) /
      3;
  
    // Determine if all indicators meet minimum threshold
    const allIndicatorsMeetThreshold =
      input.trainingCompletionRate >= MINIMUM_THRESHOLD &&
      input.manualComprehensionScore >= MINIMUM_THRESHOLD &&
      input.systemOperationProficiencyScore >= MINIMUM_THRESHOLD;
  
    const status = allIndicatorsMeetThreshold ? "ready" : "not_ready";
    const isReadyForCutover = allIndicatorsMeetThreshold;
    const missingIndicators: string[] = [];
  
    const evaluationTimestamp = new Date().toISOString();
  
    return {
      status,
      isReadyForCutover,
      readinessScore: Math.round(readinessScore * 1000) / 1000,
      missingIndicators,
      evaluationTimestamp
    };
  }
  return { evaluateTrainingCompletionReadiness };
})();
